INSERT INTO book (isbn, name, author, publisher, price, category, description, create_time, update_time, deleted) VALUES
('978-7-111-63666-3', '数据结构与算法分析：C语言描述（原书第2版）', 'Mark Allen Weiss', '机械工业出版社', 69.00, '算法与数据结构', '计算机与信息与计算科学专业核心基础课教材，系统讲解线性表、树、散列表、优先队列、排序与图论算法及复杂度分析。', '2026-08-22 09:00:00', '2026-08-22 09:00:00', 0),
