('978-7-302-51756-6', '数值分析（第5版）', '李庆扬、王能超、易大义', '清华大学出版社', 49.00, '信息与计算科学', '信息与计算科学专业主干必修教材，系统讲解插值法、函数逼近、数值积分与数值微分、解线性方程组的直接法与迭代法。', '2026-08-22 09:30:00', '2026-08-22 09:30:00', 0),
('978-7-04-051366-0', '数学分析（第五版·上册）', '华东师范大学数学科学学院', '高等教育出版社', 54.80, '信息与计算科学', '数学与信息与计算科学专业基础课程教材，涵盖实数集与函数、数列与函数极限、连续性、导数与微分及不定积分。', '2026-08-22 09:35:00', '2026-08-22 09:35:00', 0),
('978-7-111-72067-6', '数据库系统概念（原书第7版）', 'Abraham Silberschatz', '机械工业出版社', 149.00, '软件工程与开发', '数据库原理课程经典教材，详细探讨关系代数、SQL标准、B+树索引、查询执行与优化、ACID事务并发控制与恢复技术。', '2026-08-22 09:40:00', '2026-08-22 09:40:00', 0),
('978-7-115-54608-1', '操作系统导论', 'Remzi H. Arpaci-Dusseau', '人民邮电出版社', 109.90, '计算机系统与网络', '围绕CPU与内存虚拟化、多线程并发控制以及文件系统持久性三大核心主题解析现代操作系统设计机理。', '2026-08-22 09:45:00', '2026-08-22 09:45:00', 0),
('978-7-04-052108-5', '高等代数（第五版）', '北京大学数学系前代数小组', '高等教育出版社', 48.20, '信息与计算科学', '信息与计算科学专业核心代数教材，包含多项式、行列式、线性方程组、矩阵代数、二次型、线性空间与线性变换。', '2026-08-22 09:50:00', '2026-08-22 09:50:00', 0),
('978-7-302-42328-7', '机器学习', '周志华', '清华大学出版社', 88.00, '人工智能与数据科学', '系统介绍机器学习基础理论与核心算法，涵盖模型评估与选择、线性模型、决策树、神经网络、支持向量机与集成学习。', '2026-08-22 09:55:00', '2026-08-22 09:55:00', 0);
